            return FfiConverterTypeFfiTotpSetup.lift(
    callWithPointer {
    uniffiRustCallWithError(Exception) { _status ->
    UniffiLib.INSTANCE.uniffi_syncloom_core_fn_method_session_add_totp(
        it, FfiConverterString.lower(`name`),_status)
}
    }
    )
    }
    

    
