    uniffiRustCallWithError(Exception) { _status ->
    UniffiLib.INSTANCE.uniffi_syncloom_core_fn_constructor_session_connect(
        FfiConverterString.lower(`server`),FfiConverterString.lower(`token`),FfiConverterString.lower(`password`),_status)
}
    )
    }
    

        
    /**
     * Restore from keys previously saved in the keychain (see `export_secrets`).
     */
    @Throws(Exception::class) fun `fromSecrets`(`server`: kotlin.String, `token`: kotlin.String, `secrets`: kotlin.ByteArray): Session {
            return FfiConverterTypeSession.lift(
    uniffiRustCallWithError(Exception) { _status ->
    UniffiLib.INSTANCE.uniffi_syncloom_core_fn_constructor_session_from_secrets(
