sealed class Exception(message: String): kotlin.Exception(message) {
        
        class Crypto(message: String) : Exception(message)
        
        class Invalid(message: String) : Exception(message)
        
        class Http(message: String) : Exception(message)
        
        class Server(message: String) : Exception(message)
        
        class Conflict(message: String) : Exception(message)
        
        class Auth(message: String) : Exception(message)
        
        class NotFound(message: String) : Exception(message)
        
        class Io(message: String) : Exception(message)
        
        class Db(message: String) : Exception(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<Exception> {
        override fun lift(error_buf: RustBuffer.ByValue): Exception = FfiConverterTypeError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeError : FfiConverterRustBuffer<Exception> {
    override fun read(buf: ByteBuffer): Exception {
        
            return when(buf.getInt()) {
            1 -> Exception.Crypto(FfiConverterString.read(buf))
            2 -> Exception.Invalid(FfiConverterString.read(buf))
            3 -> Exception.Http(FfiConverterString.read(buf))
            4 -> Exception.Server(FfiConverterString.read(buf))
            5 -> Exception.Conflict(FfiConverterString.read(buf))
            6 -> Exception.Auth(FfiConverterString.read(buf))
            7 -> Exception.NotFound(FfiConverterString.read(buf))
            8 -> Exception.Io(FfiConverterString.read(buf))
            9 -> Exception.Db(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: Exception): ULong {
        return 4UL
    }

    override fun write(value: Exception, buf: ByteBuffer) {
        when(value) {
            is Exception.Crypto -> {
                buf.putInt(1)
                Unit
            }
            is Exception.Invalid -> {
                buf.putInt(2)
                Unit
            }
            is Exception.Http -> {
                buf.putInt(3)
                Unit
            }
            is Exception.Server -> {
                buf.putInt(4)
                Unit
            }
            is Exception.Conflict -> {
                buf.putInt(5)
                Unit
            }
            is Exception.Auth -> {
                buf.putInt(6)
                Unit
            }
            is Exception.NotFound -> {
                buf.putInt(7)
                Unit
            }
            is Exception.Io -> {
                buf.putInt(8)
                Unit
            }
            is Exception.Db -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



sealed class FfiLogin {
    
    data class Ok(
        val `token`: kotlin.String) : FfiLogin() {
        companion object
    }
    
    data class MfaRequired(
        val `token`: kotlin.String, 
        val `methods`: List<kotlin.String>) : FfiLogin() {
        companion object
    }
    
    data class EnrollRequired(
        val `token`: kotlin.String) : FfiLogin() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiLogin : FfiConverterRustBuffer<FfiLogin>{
    override fun read(buf: ByteBuffer): FfiLogin {
        return when(buf.getInt()) {
            1 -> FfiLogin.Ok(
                FfiConverterString.read(buf),
                )
            2 -> FfiLogin.MfaRequired(
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                )
            3 -> FfiLogin.EnrollRequired(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiLogin) = when(value) {
        is FfiLogin.Ok -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`token`)
            )
        }
        is FfiLogin.MfaRequired -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`token`)
                + FfiConverterSequenceString.allocationSize(value.`methods`)
            )
        }
        is FfiLogin.EnrollRequired -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`token`)
            )
        }
    }

    override fun write(value: FfiLogin, buf: ByteBuffer) {
        when(value) {
            is FfiLogin.Ok -> {
                buf.putInt(1)
                FfiConverterString.write(value.`token`, buf)
                Unit
            }
            is FfiLogin.MfaRequired -> {
                buf.putInt(2)
                FfiConverterString.write(value.`token`, buf)
                FfiConverterSequenceString.write(value.`methods`, buf)
                Unit
            }
            is FfiLogin.EnrollRequired -> {
                buf.putInt(3)
                FfiConverterString.write(value.`token`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalLong: FfiConverterRustBuffer<kotlin.Long?> {
    override fun read(buf: ByteBuffer): kotlin.Long? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterLong.read(buf)
    }

    override fun allocationSize(value: kotlin.Long?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterLong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Long?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterLong.write(value, buf)
        }
    }
}




